SELECT "Motos_2"."Marca" AS "Datos__copia_",   CAST(EXTRACT(MONTH FROM "Motos_2"."FECHA") AS BIGINT) AS "mn_FECHA_ok",   SUM("Motos_2"."InversionUS") AS "sum_Calculation_0061002123102817_ok",   CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Motos_2" WHERE ((CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) = 2015) AND ("Motos_2"."Categoria" = 'MOTOCICLETAS')) GROUP BY "Motos_2"."Marca", "mn_FECHA_ok", "yr_FECHA_ok";
